-- Correct reagent quest teaching rewards and reward displays
-- 2026_11_10_50_world_everlake_quest_learning_rewards.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): eg-link 9fcae73cc74fea4f1c4f, wago 1.60.1.70862
-- Written against the fork world core 343fe6fb + world-data 24a3b39e + reviewed drafts.
-- Efficient Games CC BY 4.0. No Classic recipe assumption: captured reward spell366567 teaches1251744 in pinned client.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';
SET SESSION autocommit = 0;
CREATE TEMPORARY TABLE `everlake_reagent_rewards` (`quest` int unsigned NOT NULL PRIMARY KEY, `npc` int unsigned NOT NULL);
INSERT INTO `everlake_reagent_rewards` (`quest`,`npc`) VALUES (2203,6868),(2501,1470);
UPDATE `quest_template` q JOIN `everlake_reagent_rewards` s ON s.`quest`=q.`ID`
SET q.`RewardSpell`=366567
WHERE q.`RewardSpell`=11522 AND q.`StartItem`=7870 AND q.`LogTitle`='Badlands Reagent Run II'
AND EXISTS (SELECT 1 FROM `quest_template_addon` a WHERE a.`ID`=q.`ID` AND a.`RequiredSkillID`=171 AND a.`RequiredSkillPoints`=210)
AND EXISTS (SELECT 1 FROM `quest_objectives` o WHERE o.`QuestID`=q.`ID` AND o.`Type`=1 AND o.`ObjectID`=7867 AND o.`Amount`=3)
AND EXISTS (SELECT 1 FROM `creature_queststarter` st JOIN `creature_questender` en ON en.`id`=st.`id` AND en.`quest`=st.`quest`
 JOIN `creature` c ON c.`id`=st.`id` JOIN `creature_template` t ON t.`entry`=c.`id`
 WHERE st.`quest`=q.`ID` AND st.`id`=s.`npc` AND c.`map`=0 AND (COALESCE(c.`npcflag`,t.`npcflag`)&2)=2)
AND EXISTS (SELECT 1 FROM `item_loot_template` l WHERE l.`Entry`=7870 AND l.`ItemType`=0 AND l.`Item`=7866 AND l.`Chance`=100 AND l.`MinCount`=3 AND l.`MaxCount`=3)
AND EXISTS (SELECT 1 FROM `spell_script_names` WHERE `spell_id`=9712 AND `ScriptName`='spell_eastern_kingdoms_thaumaturgy_channel')
AND EXISTS (SELECT 1 FROM `creature` WHERE `id`=2726 AND `map`=0);
DROP TEMPORARY TABLE `everlake_reagent_rewards`;
-- Current core loads this display table, not legacy RewardDisplaySpell1 columns
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`QuestID` int unsigned NOT NULL, `Idx` int unsigned NOT NULL, `SpellID` int unsigned NOT NULL, `PlayerConditionID` int unsigned NOT NULL, `Type` int unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`QuestID`, `Idx`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`QuestID`, `Idx`, `SpellID`, `PlayerConditionID`, `Type`, `VerifiedBuild`, `note`) VALUES
(2203, 0, 1251744, 0, 2, 0, 'EG Link 70862 displaySpells type2; Greater Mender recipe reward'),
(2501, 0, 1251744, 0, 2, 0, 'EG Link 70862 displaySpells type2; Greater Mender recipe reward'),
(94971, 0, 1279399, 0, 0, 0, 'EG Link 70862 displaySpells type0; Warhorse reward display');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `quest_reward_display_spell` t WHERE t.`QuestID` = s.`QuestID` AND t.`Idx` = s.`Idx`) AND EXISTS (SELECT 1 FROM `quest_template` q WHERE q.`ID`=s.`QuestID` AND q.`RewardSpell`=CASE WHEN s.`QuestID`=94971 THEN 1279400 ELSE 366567 END);
INSERT INTO `quest_reward_display_spell` (`QuestID`, `Idx`, `SpellID`, `PlayerConditionID`, `Type`, `VerifiedBuild`) SELECT `QuestID`, `Idx`, `SpellID`, `PlayerConditionID`, `Type`, `VerifiedBuild` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `file`, `note`) SELECT 'quest_reward_display_spell', s.`QuestID`, s.`Idx`, '2026_11_10_50_world_everlake_quest_learning_rewards.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_50_world_everlake_quest_learning_rewards.sql', `note` = s.`note`;
DROP TEMPORARY TABLE `everlake_import_stage`;

SET SESSION autocommit = 1;
